// 1. Create a custom formatter (sync, as async is not supported)
// my-formatter.js
module.exports = function(results) {
    // This is a simplified sync formatter that mimics the output style in the image
    return results.map(result => {
        let output = result.source.split('\n').map((line, idx) => {
            let lineNum = idx + 1;
            let linePrefix = (lineNum === 94 || lineNum === 97) ? `${lineNum}:` : '   ';
            return `${linePrefix}  ${line}`;
        }).join('\n');
        // Add fake inline error annotations for demonstration
        output += '\n94:   return ansiStyles[type].ansi(ansiStyles.rgbToAnsi(...arguments_));';
        output += '\n      ↑      ↑                ↑';
        output += '\n      ✖ There must be a space after this paren. ( auto-fixable )';
        output += '\n      ✖ Extra semicolon. ( auto-fixable )';
        output += '\n      ✖ There must be a space before this paren. ( auto-fixable )';
        output += '\n      ✖ There must be a space after this paren. ( auto-fixable )';
        output += '\n      ✖ A space is required before ]. ( auto-fixable )';
        output += '\n      ✖ A space is required after [. ( auto-fixable )';
        output += '\n97:   if (model === \'hex\') {';
        output += '\n      ↑      ↑';
        output += '\n      ✖ There must be a space before this paren. ( auto-fixable )';
        output += '\n      ✖ There must be a space after this paren. ( auto-fixable )';
        return output;
    }).join('\n');
};

